from math import gcd
from typing import List, Tuple


def peak_residue(q: int, r: int, j: int) -> int:
    """Residue of the j-th peak position j*q/r on the measurement grid."""
    return (j * q) % r


def certifies(q: int, r: int, j: int) -> bool:
    """Peak j is certifiable iff 2*r*m <= q or 2*r*(r-m) <= q, m = j*q mod r."""
    m = peak_residue(q, r, j)
    return (2 * r * m <= q) or (2 * r * (r - m) <= q)


def cert_count_enumerate(q: int, r: int) -> int:
    """Direct O(r) enumeration of the certifying set."""
    return sum(1 for j in range(r) if certifies(q, r, j))


def cert_count_closed(q: int, r: int) -> int:
    """Closed form: 2*floor(q/(2r)) + 1 below saturation, else r.

    Requires gcd(q, r) = 1 for the equidistribution step; for r | q the
    degenerate dyadic answer is r.
    """
    b = q // (2 * r)
    return r if r <= 2 * b + 1 else 2 * b + 1


def info_count_closed(q: int, r: int) -> int:
    """Informative certificates: 2 * #{m in [1, B] : gcd(m, r) = 1}, B = q//(2r).

    Below saturation only; at saturation the answer is Euler's totient phi(r).
    """
    b = q // (2 * r)
    if r <= 2 * b + 1:
        return sum(1 for m in range(1, r) if gcd(m, r) == 1)
    return 2 * sum(1 for m in range(1, b + 1) if gcd(m, r) == 1)


def ramp_rails(q: int, r: int) -> Tuple[float, float]:
    """The proved rails (q/r^2 - 1/r, q/r^2 + 1/r] on the per-sample rate."""
    return (q / r ** 2 - 1 / r, q / r ** 2 + 1 / r)


def regime(q: int, r: int) -> str:
    """dead (q < 2r) / ramp / saturated (r <= 2*floor(q/2r) + 1)."""
    if q < 2 * r:
        return "dead"
    return "saturated" if r <= 2 * (q // (2 * r)) + 1 else "ramp"
